{
  "title": "短路的水渍",
  "synopsis": "林岚与周野在广播站重逢，排查断电原因。周野的鲁莽导致短路，林岚冷静查明漏水真相，两人在暴雨中合作接线，却因钥匙丢失陷入僵局。",
  "preview_blurb": "老街广播站突发断电，急躁的主持人与冷静的维修员在漏电危机中被迫联手，一场暴雨让旧日心结与生锈的铁锁同时浮出水面。",
  "scenes": [
    {
      "title": "强行推闸",
      "location": "广播站配电区",
      "dramatic_goal": "展现周野的急躁与林岚的专业克制，通过短路危机确立林岚的主导地位。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哎哟！这破闸怎么卡住了？林岚你快点行不行，外头街坊都等着听天气预报呢！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "退后。别碰电闸。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "我帮你推一把——"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别动！周野，你不要命了？带电强推，你想把整个主控台烧了吗？"
        }
      ]
    },
    {
      "title": "水渍与图纸",
      "location": "广播站主控台",
      "dramatic_goal": "排查进水原因，排除人为破坏嫌疑，两人在核对图纸中产生专业拉扯。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "拿万用表给我。去念设备背面的出厂参数和接线图。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哦……这灰厚的。IP二十……防水等级IP20。这机器不防水啊。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "看地上。水渍是从天花板通风口顺着墙根流下来的，正好滴在旧电源接头上。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "你的意思是，不是有人故意泼水搞破坏？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "屋顶漏水。自然故障。把图纸递给我，核对线序。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "图纸在这儿。红线接L，蓝线接N……不对啊，这老图纸上画的是黄绿双色线接地。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "那是八零年的老国标。按新图纸来，别自作主张。"
        }
      ]
    },
    {
      "title": "丢失的钥匙",
      "location": "广播站备用线路区",
      "dramatic_goal": "在暴雨中达成初步合作接线，但主保险丝烧毁且钥匙丢失，将维修推入僵局。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "雨下大了，备用线路得马上接通。拿手电照着接线柱。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "照着呢。一号端子，黄线。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "确认。二号端子。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "绿线。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "确认。三号。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "红线。接好了！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "推闸。主保险丝烧了。去旧物柜拿备用保险丝。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "好嘞，钥匙在……哎？我兜里的钥匙呢？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "找。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "完了……刚才短路爆火花的时候，我往后一躲，钥匙好像掉进外面的下水道里了。"
        }
      ]
    }
  ],
  "episode_summary": "本集排查了广播站断电原因，确认是屋顶漏水而非人为破坏。林岚与周野在核对参数与接线中达成初步合作，但因主保险丝烧毁且备用柜钥匙掉入下水道，维修陷入僵局。",
  "ending_hook": "备用保险丝柜锁死，钥匙掉入下水道，暴雨中的广播站面临无法通电的危机。",
  "fact_delta": [
    {
      "fact": "断电原因是屋顶漏水滴入旧电源接头，排除人为破坏"
    },
    {
      "fact": "主保险丝烧毁，备用保险丝在旧物柜中"
    },
    {
      "fact": "旧物柜钥匙掉入下水道"
    }
  ],
  "relationship_delta": [
    {
      "change": "周野从急躁干预转为听从林岚的专业指挥，两人达成初步的接线合作"
    }
  ],
  "new_open_threads": [
    "如何取出下水道里的钥匙或打开旧物柜获取备用保险丝",
    "修复主保险丝后能否顺利完成广播验收"
  ],
  "closed_threads": []
}
